### Terraform Version

1.3.0

### AzureRM Provider Version

v4.35.0

### Affected Resource(s)/Data Source(s)

azurerm_api_management_subscription

### Terraform Configuration Files

```hcl
terraform {
  required_version = "= 1.3.0"

  required_providers {
    azurerm = "= 4.35.0"
    random  = "= 2.2.1"
  }
}

provider "azurerm" {
  features {}
}

# variables
variable "resource_name" {
  type        = string
}

variable "resource_group_name" {
  type        = string
}

variable "location" {
  type        = string
}

variable "sku_name" {
  type        = string
}

variable "virtual_network_name" {
  type        = string
}

variable "backend_service_url" {
  type        = string
}

variable "address_prefix" {
  type        = string
}

# data and locals
data "azurerm_client_config" "current" {}

data "azurerm_subscription" "current" {}

locals {
  resource_name = "my-api"

  apis = {
    a = {
      display_name     = "API a"
      path             = "a"
      backend_url      = "${var.backend_service_url}/a"
    }

    b = {
      display_name     = "API b"
      path             = "b"
      backend_url      = "${var.backend_service_url}/b"
    }

    c = {
      display_name     = "API c"
      path             = "c"
      backend_url      = "${var.backend_service_url}/c"
    }
  }

  subscriptions = {
    sub_a = {
      display_name = "Subscription A"
      product_key   = "a"
    },
    sub_b = {
      display_name = "Subscription B"
      product_key   = "b"
    },
    sub_c = {
      display_name = "Subscription C"
      product_key   = "b"
    },
    sub_d = {
      display_name = "Subscription D"
      product_key   = "b"
    }
  }
}

# resources
resource "azurerm_subnet" "this" {
  name                 = "my-subnet"
  resource_group_name  = var.resource_group_name
  virtual_network_name = var.virtual_network_name
  address_prefixes     = [var.address_prefix]
}

resource "azurerm_api_management" "this" {
  name                = var.resource_name
  location            = var.location
  resource_group_name = var.resource_group_name
  sku_name            = var.sku_name
  publisher_name      = "Demo"
  publisher_email     = "demo@example.com"

  virtual_network_type = "External"
  virtual_network_configuration {
    subnet_id = azurerm_subnet.this.id
  }
}

resource "azurerm_api_management_api" "apis" {
  for_each = local.apis

  name                = each.key
  resource_group_name = azurerm_api_management.this.resource_group_name
  api_management_name = azurerm_api_management.this.name
  revision            = "1"
  display_name        = each.value.display_name
  path                = each.value.path
  protocols           = ["https"]
  service_url         = each.value.backend_url

  subscription_required = true
  subscription_key_parameter_names {
    header = "Ocp-Apim-Subscription-Key"
    query  = "subscription-key"
  }
}

resource "azurerm_api_management_product" "a" {
  product_id            = "a"
  api_management_name   = azurerm_api_management.this.name
  resource_group_name   = azurerm_api_management.this.resource_group_name
  display_name          = "Product A"
  subscription_required = true
  published             = true
  approval_required     = false
}

resource "azurerm_api_management_product_api" "a" {
  api_name            = azurerm_api_management_api.apis["a"].name
  product_id          = azurerm_api_management_product.a.product_id
  api_management_name = azurerm_api_management.this.name
  resource_group_name = azurerm_api_management.this.resource_group_name
}

resource "azurerm_api_management_product" "b" {
  product_id            = "b"
  api_management_name   = azurerm_api_management.this.name
  resource_group_name   = azurerm_api_management.this.resource_group_name
  display_name          = "Product B"
  subscription_required = true
  published             = true
  approval_required     = false
}

resource "azurerm_api_management_product_api" "b" {
  api_name            = azurerm_api_management_api.apis["b"].name
  product_id          = azurerm_api_management_product.b.product_id
  api_management_name = azurerm_api_management.this.name
  resource_group_name = azurerm_api_management.this.resource_group_name
}

resource "random_string" "user_id" {
  length  = 16
  number  = true
  special = false
}

resource "azurerm_api_management_user" "demo" {
  user_id             = random_string.user_id.result
  api_management_name = azurerm_api_management.this.name
  resource_group_name = azurerm_api_management.this.resource_group_name
  first_name          = "De"
  last_name           = "Mo"
  email               = "user@example.com"
  state               = "active"
}

resource "azurerm_api_management_subscription" "subscriptions" {
  for_each = local.subscriptions

  api_management_name = azurerm_api_management.this.name
  resource_group_name = azurerm_api_management.this.resource_group_name
  user_id             = azurerm_api_management_user.demo.id
  product_id          = azurerm_api_management_product[each.value.product_key].id
  display_name        = each.value.display_name

  depends_on = [
    azurerm_api_management_product_api,
    azurerm_api_management_user
  ]
}
```

### Debug Output/Panic Output

```shell
unexpected status 412 (412 Precondition Failed) with error: PreconditionFailed: Resource was modified since last retrieval.
```

### Expected Behaviour

Multiple subscriptions should be created in a single execution. Only 1 or 2 subscriptions are created and throwing error for other subscriptions. Rerunning tf apply will create the remaining subscriptions.

### Actual Behaviour

This is same issue asked in 
https://github.com/hashicorp/terraform-provider-azurerm/issues/8571

Solution suggested in above issue is to add depends on condition in second subscription of first subscription. So that second sub will execute after first sub. But in our case we are creating multiple subscriptions on same product key using for_each.

How to handle this precondition error in this case?

### Steps to Reproduce

