    "recover",
    "restore",
    "set",
  ]
}

resource "azurerm_key_vault_certificate" "this" {
    name = "my-certificate"
    key_vault_id = azurerm_key_vault.this.id

    depends_on = [
        azurerm_key_vault_access_policy.this
    ]

    certificate_policy {
        issuer_parameters {
          name = "Self"
        }

        key_properties {
            exportable = false
            key_size = 4096
            key_type = "RSA"
